CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE "user_role" AS ENUM ('user', 'admin');
CREATE TYPE "user_status" AS ENUM ('active', 'suspended');
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "email" text NOT NULL UNIQUE, "password_hash" text NOT NULL, "role" "user_role" NOT NULL DEFAULT 'user', "status" "user_status" NOT NULL DEFAULT 'active', "email_verified_at" timestamptz, "last_login_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "profiles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL UNIQUE REFERENCES "users"("id") ON DELETE CASCADE, "first_name" text NOT NULL, "last_name" text NOT NULL, "phone" text, "avatar_url" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "token_hash" text NOT NULL UNIQUE, "expires_at" timestamptz NOT NULL, "last_seen_at" timestamptz NOT NULL DEFAULT now(), "ip_address" inet, "user_agent" text, "impersonator_id" uuid REFERENCES "users"("id") ON DELETE SET NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "email_verification_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "token_hash" text NOT NULL UNIQUE, "expires_at" timestamptz NOT NULL, "used_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "password_reset_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "token_hash" text NOT NULL UNIQUE, "expires_at" timestamptz NOT NULL, "used_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "audit_logs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "actor_id" uuid REFERENCES "users"("id") ON DELETE SET NULL, "target_user_id" uuid REFERENCES "users"("id") ON DELETE SET NULL, "action" text NOT NULL, "metadata" jsonb NOT NULL DEFAULT '{}', "ip_address" inet, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "notifications" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "title" text NOT NULL, "body" text NOT NULL, "read" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "users_email_idx" ON "users" ("email"); CREATE INDEX "sessions_user_id_idx" ON "sessions" ("user_id"); CREATE INDEX "sessions_expires_at_idx" ON "sessions" ("expires_at"); CREATE INDEX "verification_tokens_user_id_idx" ON "email_verification_tokens" ("user_id"); CREATE INDEX "password_reset_tokens_user_id_idx" ON "password_reset_tokens" ("user_id"); CREATE INDEX "notifications_user_id_idx" ON "notifications" ("user_id");
